import { useState, useMemo, useEffect } from "react";
import { useParams, useLocation } from "wouter";
import { useNetworkGuard } from "@/hooks/useNetworkGuard";
import { useQuery } from "@tanstack/react-query";
import { ChevronLeft, Shield, PawPrint, Clock, Check, Users, Handshake, CreditCard, Lock } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { MobileDatePicker } from "@/components/ui/mobile-date-picker";
import { useToast } from "@/hooks/use-toast";
import { apiRequest } from "@/lib/queryClient";
import { vatCalculator } from "@/lib/vatCalculator";
import { getActivePaymentMethod, PAYMENTS_CONFIG } from "@/lib/paymentConfig";
import { WeatherConsentDialog, useWeatherConsent } from "@/components/weather/WeatherConsentDialog";
import { OwnerInstructionsForm, useOwnerInstructions } from "@/components/booking/OwnerInstructionsForm";
import { CreditWalletCard } from "@/components/wallet/CreditWalletCard";
import { PrestigePassPaymentOption } from "@/components/PrestigePassPaymentOption";
import { WalletCheckoutPreview } from "@/components/wallet/WalletCheckoutPreview";
import { useFirebaseAuth } from "@/auth/AuthProvider";
import { type PlaceDetails } from "@/components/ui/google-places-autocomplete";
import { AddressPicker } from "@/components/ui/address-picker";
import { NavigationButton } from "@/components/NavigationButton";

type BookingStep = "details" | "summary" | "pending_match" | "confirmation";

export default function WalkBookingFlow() {
  const { walkerId } = useParams();
  const [, setLocation] = useLocation();
  const { toast } = useToast();
  const { user } = useFirebaseAuth();
  const { assertConnected } = useNetworkGuard();

  const walkerIdNumber = walkerId ? parseInt(walkerId) : undefined;

  const [step, setStep] = useState<BookingStep>("details");
  const [selectedPetIds, setSelectedPetIds] = useState<number[]>([]);
  const [selectedDate, setSelectedDate] = useState<Date | null>(null);
  const [duration, setDuration] = useState<number>(60); // minutes
  const [notes, setNotes] = useState("");
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [bookingId, setBookingId] = useState<string | null>(null);
  const [appliedCredits, setAppliedCredits] = useState<{ redemptionSessionId: string; totalCreditsAppliedCents: number; cashDueCents: number } | null>(null);
  const [pickupAddress, setPickupAddress] = useState('');
  const [pickupDetails, setPickupDetails] = useState<PlaceDetails | null>(null);

  // Pre-fill pickup address from user's saved profile
  const { data: userProfile } = useQuery<{
    address: string; street: string; streetNumber?: string; apartment?: string;
    city: string; postalCode: string; latitude: number | null; longitude: number | null;
    addressIsTemporary?: boolean; temporaryAddress?: string; temporaryLat?: number | null; temporaryLng?: number | null;
  }>({
    queryKey: ['/api/user/profile'],
    enabled: !!user?.uid,
  });

  useEffect(() => {
    if (!userProfile || pickupAddress) return;
    // Prefer temporary address when flagged, otherwise use permanent address
    if (userProfile.addressIsTemporary && userProfile.temporaryAddress) {
      setPickupAddress(userProfile.temporaryAddress);
      if (userProfile.temporaryLat && userProfile.temporaryLng) {
        setPickupDetails({
          formattedAddress: userProfile.temporaryAddress,
          lat: userProfile.temporaryLat,
          lng: userProfile.temporaryLng,
        });
      }
    } else if (userProfile.address || userProfile.street) {
      const full = userProfile.address ||
        [userProfile.street, userProfile.streetNumber, userProfile.apartment, userProfile.city, userProfile.postalCode]
          .filter(Boolean).join(', ');
      setPickupAddress(full);
      if (userProfile.latitude && userProfile.longitude) {
        setPickupDetails({
          formattedAddress: full,
          street: userProfile.street,
          city: userProfile.city,
          postalCode: userProfile.postalCode,
          lat: userProfile.latitude,
          lng: userProfile.longitude,
        });
      }
    }
  }, [userProfile]);
  const [showWeatherConsent, setShowWeatherConsent] = useState(false);
  const [weatherConsentAccepted, setWeatherConsentAccepted] = useState(false);
  const [weatherConditions, setWeatherConditions] = useState<string[]>([]);
  const { instructions: ownerInstructions, setInstructions: setOwnerInstructions } = useOwnerInstructions();

  // Check if weather consent is needed for the selected date
  const { data: weatherCheck } = useWeatherConsent(selectedDate);

  // Real-time polling for provider acceptance — same pattern as Sitter Suite
  const { data: bookingStatus } = useQuery({
    queryKey: [`/api/walk-my-pet/walks/bookings/${bookingId}/status`],
    enabled: step === 'pending_match' && !!bookingId,
    refetchInterval: 5000,
  });

  useEffect(() => {
    if (step === 'pending_match' && bookingStatus) {
      const status = (bookingStatus as any)?.status;
      if (status === 'accepted' || status === 'confirmed') {
        setStep('confirmation');
        toast({
          title: "יש התאמה! 🎉",
          description: "המוליך/ה אישר/ה את הבקשה. ההזמנה מאושרת!",
        });
      }
    }
  }, [step, bookingStatus, toast]);

  // Fetch specific walker data using ID filter — avoids loading all walkers
  const { data: providersData, isLoading: walkerLoading, error: walkerError } = useQuery({
    queryKey: ['/api/platforms/walk_my_pet/providers', walkerIdNumber],
    queryFn: async () => {
      const res = await fetch(`/api/platforms/walk_my_pet/providers?id=${walkerIdNumber}`, {
        credentials: 'include',
      });
      if (!res.ok) throw new Error('Failed to fetch walker');
      return res.json();
    },
    enabled: !!walkerIdNumber,
  });

  // Fetch user's pets from real API
  const { data: petsData, isLoading: petsLoading } = useQuery({
    queryKey: ['/api/pets'],
    enabled: step === 'details',
  });

  const providers = Array.isArray(providersData) ? providersData : [];
  const walker = providers.find((p: any) => Number(p.id) === walkerIdNumber);
  const pets = Array.isArray(petsData) ? petsData : (petsData?.pets || []);

  // Auto-select pet if user has exactly one pet
  useEffect(() => {
    if (pets.length === 1 && selectedPetIds.length === 0) {
      setSelectedPetIds([pets[0].id]);
    }
  }, [pets, selectedPetIds]);

  // Calculate pricing using VAT calculator
  const baseAmount = useMemo(() => {
    if (!walker?.hourlyRate) return 0;
    return walker.hourlyRate * (duration / 60); // Pro-rate for duration
  }, [walker, duration]);

  const pricing = useMemo(() => {
    return vatCalculator.calculateVAT(baseAmount);
  }, [baseAmount]);

  const canContinueDetails = useMemo(() => {
    return (
      !!walker &&
      selectedPetIds.length > 0 &&
      !!selectedDate &&
      duration > 0 &&
      pickupAddress.trim().length > 0
    );
  }, [walker, selectedPetIds, selectedDate, duration, pickupAddress]);

  async function handleNextFromDetails() {
    if (!canContinueDetails) {
      toast({
        title: "נדרשים פרטים נוספים",
        description: "יש למלא את כל השדות לפני המשך",
        variant: "destructive",
      });
      return;
    }
    
    // Check if weather consent is needed for adverse conditions
    if (weatherCheck?.needsConsent && !weatherConsentAccepted) {
      setShowWeatherConsent(true);
      return;
    }
    
    setStep("summary");
  }
  
  function handleWeatherConsent(accepted: boolean, conditions: string[]) {
    if (accepted) {
      setWeatherConsentAccepted(true);
      setWeatherConditions(conditions);
      setStep("summary");
    } else {
      toast({
        title: "הזמנה בוטלה",
        description: "ניתן לבחור תאריך אחר עם תנאי מזג אוויר טובים יותר",
      });
    }
  }

  async function handleConfirmBooking() {
    if (!walker || !selectedDate || !walkerIdNumber) return;

    try {
      setIsSubmitting(true);

      // Network connectivity check before committing booking
      await assertConnected('he');

      // Use local-date extraction to avoid UTC/local timezone mismatch.
      // toISOString() yields UTC date which can be one day off for Israeli users (UTC+2/+3).
      const pad2 = (n: number) => String(n).padStart(2, '0');
      const scheduledDate = `${selectedDate.getFullYear()}-${pad2(selectedDate.getMonth() + 1)}-${pad2(selectedDate.getDate())}`;
      const scheduledStartTime = `${pad2(selectedDate.getHours())}:${pad2(selectedDate.getMinutes())}`;

      // Resolve actual pet data from the user's pet list so the walker sees real pet info.
      const selectedPets = pets.filter((p: any) => selectedPetIds.includes(p.id));
      const primaryPet = selectedPets[0] as any;

      const payload = {
        walkerId: walker.walkerId || `WALKER-${walkerIdNumber}`,
        scheduledDate,
        scheduledStartTime,
        durationMinutes: duration,
        pickupLatitude: pickupDetails?.lat ?? walker.latitude ?? 32.0853,
        pickupLongitude: pickupDetails?.lng ?? walker.longitude ?? 34.7818,
        pickupAddress: pickupAddress || walker.serviceArea || '',
        petName: primaryPet?.name ?? primaryPet?.petName ?? 'Pet',
        petBreed: primaryPet?.breed ?? primaryPet?.petBreed ?? 'Mixed',
        petWeight: primaryPet?.weight ?? primaryPet?.petWeight ?? 10,
        petSpecialNeeds: primaryPet?.specialNeeds ?? primaryPet?.medicalNotes ?? notes ?? '',
        notes,
        petIds: selectedPetIds,
        pricing: {
          currency: "ILS",
          baseAmount: pricing.baseAmount,
          commission: pricing.commission,
          vatAmount: pricing.vatOnCommission,
          totalAmount: pricing.totalCharged
        },
        platformData: {
          walkerName: walker.businessName || walker.displayName || 'Professional Walker',
          serviceArea: walker.serviceArea || 'Service Area',
          duration,
          paymentMethod: getActivePaymentMethod(),
          timezone: Intl.DateTimeFormat().resolvedOptions().timeZone
        },
        // Two-way matching: requires provider approval
        requiresProviderApproval: true,
        // Weather consent data (if applicable)
        weatherConsent: weatherConsentAccepted ? {
          customerAccepted: true,
          acceptedAt: new Date().toISOString(),
          conditions: weatherConditions,
          adverseWeather: weatherCheck?.weather?.isAdverse || false,
          adverseReason: weatherCheck?.weather?.adverseReason || null
        } : null,
        // Owner instructions (only if consent given)
        ownerInstructions: ownerInstructions.shareWithProvider ? {
          gateCode: ownerInstructions.gateCode,
          doorCode: ownerInstructions.doorCode,
          alarmCode: ownerInstructions.alarmCode,
          alarmInstructions: ownerInstructions.alarmInstructions,
          airconLocation: ownerInstructions.airconLocation,
          foodLocation: ownerInstructions.foodLocation,
          waterLocation: ownerInstructions.waterLocation,
          medicationInstructions: ownerInstructions.medicationInstructions,
          emergencyContact: ownerInstructions.emergencyContact,
          vetContact: ownerInstructions.vetContact,
          additionalNotes: ownerInstructions.additionalNotes,
        } : null,
        ...(appliedCredits ? {
          redemptionSessionId: appliedCredits.redemptionSessionId,
          creditsAppliedCents: appliedCredits.totalCreditsAppliedCents,
          cashDueCents: appliedCredits.cashDueCents,
        } : {})
      };

      const response = await apiRequest('POST', '/api/walk-my-pet/walks/book', payload);
      const booking = await response.json();

      setBookingId(booking.booking?.id || booking.id || booking.bookingNumber || 'pending');
      
      // Open chat conversation
      if (booking.booking?.id || booking.id) {
        apiRequest('POST', `/api/booking-chat/${booking.booking?.id || booking.id}/open`).catch(err => {
          console.error('Failed to open booking chat:', err);
        });
      }

      // Mark first booking as complete for push notification permission (Apple compliance)
      localStorage.setItem('petwash_first_booking_complete', 'true');

      // Show pending match step for two-way consent (like Uber/Tinder matching)
      setStep("pending_match");

      toast({
        title: "בקשת הליכה נשלחה! 🐾",
        description: "ממתינים לאישור המוליך/ה. תקבל/י התראה כשיהיה התאמה.",
      });
    } catch (error: any) {
      toast({
        title: "שגיאה ביצירת הזמנה",
        description: error.message || "אירעה שגיאה. אין חיוב. נסה/י שוב.",
        variant: "destructive",
      });
    } finally {
      setIsSubmitting(false);
    }
  }

  function togglePet(id: number) {
    setSelectedPetIds(prev =>
      prev.includes(id) ? prev.filter(p => p !== id) : [...prev, id]
    );
  }

  // Loading state
  if (walkerLoading || petsLoading) {
    return (
      <div className="flex h-screen items-center justify-center bg-white">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-500 mx-auto mb-4"></div>
          <p className="text-slate-600 font-light">טוען את נתוני המוליך/ה...</p>
        </div>
      </div>
    );
  }

  // Error state
  if (walkerError || !walker) {
    return (
      <div className="flex h-screen items-center justify-center bg-white">
        <div className="text-center max-w-md px-4">
          <h2 className="text-2xl font-light mb-4 text-slate-900">לא נמצא/ה מוליך/ה</h2>
          <p className="text-slate-600 font-light mb-6">
            המוליך/ה לא זמינ/ה כרגע או שהקישור שגוי.
          </p>
          <Button onClick={() => setLocation("/walk-my-pet")} className="bg-blue-500 text-white font-light">
            חזרה לרשימת מוליכים
          </Button>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen luxury-bg-mesh">
      {/* Header */}
      <div className="luxury-glass-panel border-b border-white/10">
        <div className="max-w-3xl mx-auto px-4 py-6">
          <button
            className="luxury-btn-ghost mb-4"
            onClick={() => setLocation("/walk-my-pet")}
            data-testid="button-back"
          >
            <ChevronLeft className="h-4 w-4 mr-2" />
            חזרה למוליכים
          </button>

          <h1 className="luxury-heading-md luxury-text-gradient" data-testid="page-title">
            הזמנת {walker.businessName || walker.displayName}
          </h1>
        </div>
      </div>

      {/* 24/7 Availability Banner */}
      <div className="max-w-3xl mx-auto px-4 pt-4">
        <div className="bg-gradient-to-r from-emerald-500/10 to-blue-500/10 rounded-xl p-3 border border-emerald-200/50 text-center">
          <p className="text-sm text-emerald-800 font-medium">
            🐾 שירות 24/7 כל השנה
          </p>
        </div>
      </div>

      {/* Progress Stepper */}
      <div className="max-w-3xl mx-auto px-4 py-6">
        <div className="flex items-center justify-center gap-1 sm:gap-2 mb-8 luxury-fade-in">
          {/* Step 1: Details */}
          <div className={`w-8 h-8 sm:w-10 sm:h-10 rounded-full flex items-center justify-center text-xs sm:text-sm font-semibold transition-all ${step === 'details' ? 'bg-gradient-to-r from-blue-500 to-blue-600 text-white luxury-shadow-lg' : ['summary', 'pending_match', 'confirmation'].includes(step) ? 'luxury-gradient-border bg-white text-blue-600' : 'bg-white text-slate-500'}`}>
            1
          </div>
          <div className={`h-1 w-8 sm:w-12 rounded-full ${['summary', 'pending_match', 'confirmation'].includes(step) ? 'bg-blue-500' : 'bg-white'}`}></div>
          {/* Step 2: Summary */}
          <div className={`w-8 h-8 sm:w-10 sm:h-10 rounded-full flex items-center justify-center text-xs sm:text-sm font-semibold transition-all ${step === 'summary' ? 'bg-gradient-to-r from-blue-500 to-blue-600 text-white luxury-shadow-lg' : ['pending_match', 'confirmation'].includes(step) ? 'luxury-gradient-border bg-white text-blue-600' : 'bg-white text-slate-500'}`}>
            2
          </div>
          <div className={`h-1 w-8 sm:w-12 rounded-full ${['pending_match', 'confirmation'].includes(step) ? 'bg-amber-500' : 'bg-white'}`}></div>
          {/* Step 3: Matching */}
          <div className={`w-8 h-8 sm:w-10 sm:h-10 rounded-full flex items-center justify-center text-xs sm:text-sm font-semibold transition-all ${step === 'pending_match' ? 'bg-gradient-to-r from-amber-400 to-orange-500 text-white luxury-shadow-lg animate-pulse' : step === 'confirmation' ? 'luxury-gradient-border bg-white text-amber-600' : 'bg-white text-slate-500'}`}>
            3
          </div>
          <div className={`h-1 w-8 sm:w-12 rounded-full ${step === 'confirmation' ? 'bg-emerald-500' : 'bg-white'}`}></div>
          {/* Step 4: Confirmed */}
          <div className={`w-8 h-8 sm:w-10 sm:h-10 rounded-full flex items-center justify-center text-xs sm:text-sm font-semibold transition-all ${step === 'confirmation' ? 'bg-gradient-to-r from-emerald-500 to-emerald-600 text-white luxury-shadow-lg' : 'bg-white text-slate-500'}`}>
            4
          </div>
        </div>
        {/* Step Labels */}
        <div className="flex items-center justify-center gap-6 text-xs text-slate-500">
          <span className={step === 'details' ? 'text-blue-600 font-medium' : ''}>פרטים</span>
          <span className={step === 'summary' ? 'text-blue-600 font-medium' : ''}>סיכום</span>
          <span className={step === 'pending_match' ? 'text-amber-600 font-medium' : ''}>התאמה</span>
          <span className={step === 'confirmation' ? 'text-emerald-600 font-medium' : ''}>אישור</span>
        </div>
      </div>

      {/* Main Content */}
      <div className="max-w-3xl mx-auto px-4 pb-12">
        
        {/* Step 1: Details */}
        {step === "details" && (
          <>
            {/* Walker Info Card */}
            <section className="mb-6 luxury-glass-card luxury-shadow-xl luxury-stagger-item p-6">
              <div className="flex items-center gap-3">
                {walker.profilePictureUrl ? (
                  <img
                    src={walker.profilePictureUrl}
                    alt={walker.businessName || walker.displayName}
                    className="h-16 w-16 rounded-full object-cover border-2 border-blue-200"
                  />
                ) : (
                  <div className="h-16 w-16 rounded-full bg-blue-100 flex items-center justify-center text-xl font-semibold text-blue-700">
                    {(walker.businessName || walker.displayName || 'W').charAt(0)}
                  </div>
                )}
                <div className="flex-1">
                  <div className="luxury-heading-sm">
                    {walker.businessName || walker.displayName}
                  </div>
                  <div className="text-sm text-slate-600">
                    {walker.serviceArea || 'שירות הליכה'} · ⭐ {walker.rating?.toFixed(1) || '5.0'}
                  </div>
                  <div className="text-xs text-slate-500 mt-1">
                    {walker.yearsOfExperience || 0} שנות ניסיון
                  </div>
                </div>
              </div>
            </section>

            {/* Pet Selection */}
            <section className="mb-6 luxury-glass-card luxury-shadow-xl luxury-stagger-item p-6">
              <div className="mb-4 luxury-heading-sm flex items-center gap-2">
                <PawPrint className="h-4 w-4 text-blue-500" />
                כלבים להליכה
              </div>
              {pets.length === 0 ? (
                <div className="text-center py-4 space-y-3">
                  <p className="luxury-text-body">אין כלבים ברשומה.</p>
                  <button
                    type="button"
                    onClick={() => setLocation('/pets')}
                    className="rounded-full px-5 py-3 min-h-[44px] text-sm font-medium bg-blue-500 text-white shadow-md transition-all"
                  >
                    + הוסף כלב
                  </button>
                </div>
              ) : (
                <div className="flex flex-wrap gap-2">
                  {pets.map((pet: any) => {
                    const active = selectedPetIds.includes(pet.id);
                    return (
                      <button
                        key={pet.id}
                        type="button"
                        onClick={() => togglePet(pet.id)}
                        className={`rounded-full px-5 py-3 min-h-[44px] text-sm transition-all touch-manipulation ${
                          active
                            ? "bg-blue-500 text-white shadow-md"
                            : "bg-white text-slate-700 border border-slate-200"
                        }`}
                        data-testid={`button-pet-${pet.id}`}
                      >
                        {pet.name}
                      </button>
                    );
                  })}
                </div>
              )}
            </section>

            {/* Date & Time */}
            <section className="mb-6 luxury-glass-card luxury-shadow-xl luxury-stagger-item p-6">
              <div className="mb-4 luxury-heading-sm flex items-center gap-2">
                <Clock className="h-4 w-4 text-blue-500" />
                תאריך ושעת התחלה
              </div>
              <MobileDatePicker
                value={selectedDate || undefined}
                onChange={(date) => setSelectedDate(date)}
                minDate={new Date()}
                includeTime={true}
                label=""
              />
              <div className="mt-4 flex items-center justify-between">
                <span className="text-sm text-slate-600">משך הליכה (דקות)</span>
                <select
                  value={duration}
                  onChange={e => setDuration(Number(e.target.value))}
                  className="w-32 rounded-xl border border-slate-200 bg-white px-3 py-2 text-sm"
                  data-testid="select-duration"
                >
                  <option value={30}>30 דקות</option>
                  <option value={60}>60 דקות</option>
                  <option value={90}>90 דקות</option>
                  <option value={120}>120 דקות</option>
                </select>
              </div>
            </section>

            {/* Pickup Address */}
            <section className="mb-6 luxury-glass-card luxury-shadow-xl luxury-stagger-item p-6">
              <AddressPicker
                label="כתובת לאיסוף"
                required
                value={pickupAddress}
                onChange={(val, details) => {
                  setPickupAddress(val);
                  if (details) setPickupDetails(details);
                  else if (!val) setPickupDetails(null);
                }}
                onPlaceSelected={(details) => setPickupDetails(details)}
                placeholder="הקלד/י את כתובת האיסוף..."
                isHebrew
                autoSave
              />
            </section>

            {/* Notes */}
            <section className="mb-6 luxury-glass-card luxury-shadow-xl luxury-stagger-item p-6">
              <div className="mb-2 text-sm font-semibold text-slate-700">
                הערות (אופציונלי)
              </div>
              <Textarea
                value={notes}
                onChange={e => setNotes(e.target.value)}
                rows={3}
                className="luxury-glass-minimal w-full resize-none px-4 py-3 text-sm"
                placeholder="התנהגות הכלב, רגישויות, מסלול מועדף, וכו׳"
                data-testid="textarea-notes"
              />
            </section>

            {/* Owner Instructions (codes, locations, etc.) */}
            <OwnerInstructionsForm
              value={ownerInstructions}
              onChange={setOwnerInstructions}
              className="mb-6 luxury-shadow-xl luxury-stagger-item"
            />

            {/* Pricing Summary */}
            <div className="mb-6 luxury-glass-card luxury-shadow-xl luxury-hover-glow luxury-stagger-item p-6">
              <div className="mb-3 flex items-center justify-between luxury-text-body">
                <span>מחיר השירות</span>
                <span>₪{pricing.grossCollectedILS.toFixed(2)}</span>
              </div>
              <div className="mb-1 flex items-center justify-between luxury-text-small opacity-70 pl-3 border-l-2 border-purple-100">
                <span>כולל עמלת PetWash (15%)</span>
                <span>₪{pricing.commission.toFixed(2)}</span>
              </div>
              <div className="mb-4 flex items-center justify-between luxury-text-small opacity-70 pl-3 border-l-2 border-purple-100">
                <span>מהם מע״מ (18/118)</span>
                <span>₪{pricing.vatOnCommission.toFixed(2)}</span>
              </div>
              <div className="pt-4 border-t border-purple-100 flex items-center justify-between">
                <span className="luxury-heading-sm">סה״כ לחיוב</span>
                <span className="luxury-heading-lg luxury-text-gradient">
                  ₪{pricing.totalCharged.toFixed(2)}
                </span>
              </div>
              <div className="mt-4 luxury-text-small leading-relaxed opacity-80">
                <Shield className="h-3 w-3 inline mr-1 text-blue-500" />
                הסכום ייושמר מהארנק שלך עם אישור המוליך/ה, ויחויב לאחר סיום ההליכה.
              </div>
            </div>

            {/* Continue Button */}
            <Button
              className="luxury-btn-primary luxury-shadow-xl w-full h-14 luxury-stagger-item"
              disabled={!canContinueDetails}
              onClick={handleNextFromDetails}
              data-testid="button-continue"
            >
              המשך לאישור
            </Button>
          </>
        )}

        {/* Step 2: Summary */}
        {step === "summary" && (
          <>
            <h2 className="luxury-heading-md mb-8 luxury-fade-in">סיכום הזמנה</h2>
            
            <div className="mb-6 luxury-glass-card luxury-shadow-xl luxury-stagger-item p-6 space-y-3">
              <div className="luxury-heading-sm">
                {walker.businessName || walker.displayName}
              </div>
              <div className="luxury-text-body">
                תאריך: {selectedDate ? selectedDate.toLocaleString("he-IL") : "-"}
              </div>
              <div className="luxury-text-body">
                משך: {duration} דקות
              </div>
              <div className="luxury-text-body">
                כלבים: {pets.filter((p: any) => selectedPetIds.includes(p.id)).map((p: any) => p.name).join(", ")}
              </div>
            </div>

            <div className="mb-6 luxury-glass-card luxury-shadow-xl luxury-hover-glow luxury-stagger-item p-6">
              <div className="mb-4 luxury-heading-sm">פירוט מחיר</div>
              <div className="mb-2 flex items-center justify-between luxury-text-small">
                <span>מחיר השירות</span>
                <span>₪{pricing.grossCollectedILS.toFixed(2)}</span>
              </div>
              <div className="mb-2 flex items-center justify-between luxury-text-small opacity-70 pl-3 border-l-2 border-purple-100">
                <span>כולל עמלת PetWash + מע״מ</span>
                <span>₪{(pricing.commission + pricing.vatOnCommission).toFixed(2)}</span>
              </div>
              <div className="pt-4 border-t border-purple-100 flex items-center justify-between">
                <span className="luxury-heading-sm">סה״כ</span>
                <span className="luxury-heading-lg luxury-text-gradient">₪{pricing.totalCharged.toFixed(2)}</span>
              </div>
              {appliedCredits && (
                <div className="mt-3 pt-3 border-t border-purple-100 space-y-1">
                  <div className="flex items-center justify-between luxury-text-small text-emerald-600">
                    <span>קרדיטים שהופעלו</span>
                    <span>-₪{(appliedCredits.totalCreditsAppliedCents / 100).toFixed(2)}</span>
                  </div>
                  <div className="flex items-center justify-between luxury-heading-sm">
                    <span>לתשלום במזומן</span>
                    <span className="luxury-text-gradient">₪{(appliedCredits.cashDueCents / 100).toFixed(2)}</span>
                  </div>
                </div>
              )}
              <div className="mt-4 luxury-text-small opacity-80">
                התשלום יתואם לאחר ההזמנה.
              </div>
            </div>

            <WalletCheckoutPreview
              subtotalCents={Math.round(pricing.totalCharged * 100)}
              divisionCode="walkers"
              className="mb-6 luxury-stagger-item"
            />

            {user && (
              <div className="mb-6 luxury-stagger-item">
                <CreditWalletCard
                  userId={user.uid}
                  platform="walker"
                  transactionAmountCents={Math.round(pricing.totalCharged * 100)}
                  onRedeemCredits={(preview, redemption) => {
                    setAppliedCredits({
                      redemptionSessionId: redemption.sessionId,
                      totalCreditsAppliedCents: preview.totalCreditsApplicableCents,
                      cashDueCents: redemption.cashDueCents,
                    });
                  }}
                />
              </div>
            )}

            {/* PrestigePass Payment Option */}
            {user && pricing.totalCharged > 0 && (
              <div className="mb-4">
                <PrestigePassPaymentOption
                  bookingId={bookingId || `PENDING-WALKER-${user.uid.slice(0, 8)}`}
                  serviceType="dog_walker"
                  amountGross={Math.round(pricing.totalCharged * 100)}
                />
              </div>
            )}

            {/* Payment Method Disclosure */}
            <section className="mb-6 luxury-glass-card luxury-shadow-xl luxury-stagger-item p-6">
              <div className="flex items-center gap-2 mb-4 luxury-heading-sm">
                <CreditCard className="h-4 w-4 text-blue-500" />
                אמצעי תשלום
              </div>
              
              {PAYMENTS_CONFIG.enableCreditCard && !PAYMENTS_CONFIG.enableNayax && (
                <div className="flex items-center gap-3 p-3 bg-white rounded-xl border border-slate-100 mb-4">
                  <div className="h-10 w-10 rounded-full bg-blue-100 flex items-center justify-center">
                    <CreditCard className="h-5 w-5 text-blue-600" />
                  </div>
                  <div>
                    <div className="text-sm font-semibold text-slate-900">כרטיס אשראי שמור</div>
                    <div className="text-xs text-slate-500">החיוב יתבצע רק לאחר סיום השירות</div>
                  </div>
                  <Lock className="h-4 w-4 text-slate-300 ml-auto" />
                </div>
              )}

              <div className="p-4 bg-blue-50/50 border border-blue-100 rounded-xl flex gap-3">
                <Shield className="h-5 w-5 text-blue-500 flex-shrink-0 mt-0.5" />
                <div className="text-sm text-blue-800 leading-relaxed">
                  <span className="font-semibold block mb-1">הגנת ⁦Pet Wash™⁩</span>
                  {PAYMENTS_CONFIG.escrowMessage.he} הכרטיס שלך לא יחויב כעת.
                </div>
              </div>
            </section>

            <div className="flex gap-4 luxury-stagger-item">
              <Button
                variant="outline"
                className="luxury-btn-secondary flex-1 h-14"
                onClick={() => setStep("details")}
                data-testid="button-back-summary"
              >
                חזרה
              </Button>
              <Button
                className="luxury-btn-primary luxury-shadow-xl flex-1 h-14"
                onClick={handleConfirmBooking}
                disabled={isSubmitting}
                data-testid="button-confirm"
              >
                {isSubmitting ? "שולח..." : "אישור והמשך"}
              </Button>
            </div>
          </>
        )}

        {/* Step 3: Pending Match (Two-Way Consent - Like Uber/Tinder) */}
        {step === "pending_match" && (
          <div className="text-center py-12 luxury-fade-in">
            <div className="w-24 h-24 rounded-full bg-gradient-to-r from-amber-400 to-orange-500 mx-auto flex items-center justify-center mb-6 luxury-shadow-xl animate-pulse">
              <Handshake className="h-12 w-12 text-white" />
            </div>
            <h2 className="luxury-heading-lg mb-4">ממתינים להתאמה...</h2>
            <p className="luxury-text-body max-w-md mx-auto mb-3">
              הבקשה נשלחה ל{walker?.businessName || walker?.displayName || 'המוליך/ה'}
            </p>
            <p className="luxury-text-small max-w-md mx-auto mb-4">
              מספר בקשה: {bookingId || "בבדיקה"}
            </p>
            
            {/* Matching Animation */}
            <div className="flex items-center justify-center gap-4 my-8">
              <div className="w-16 h-16 rounded-full bg-gradient-to-br from-blue-100 to-blue-200 flex items-center justify-center border-2 border-blue-300">
                <Users className="h-8 w-8 text-blue-600" />
              </div>
              <div className="flex gap-1">
                <div className="w-3 h-3 rounded-full bg-amber-400 animate-bounce" style={{ animationDelay: '0ms' }}></div>
                <div className="w-3 h-3 rounded-full bg-amber-500 animate-bounce" style={{ animationDelay: '150ms' }}></div>
                <div className="w-3 h-3 rounded-full bg-orange-500 animate-bounce" style={{ animationDelay: '300ms' }}></div>
              </div>
              <div className="w-16 h-16 rounded-full bg-gradient-to-br from-emerald-100 to-emerald-200 flex items-center justify-center border-2 border-emerald-300">
                <PawPrint className="h-8 w-8 text-emerald-600" />
              </div>
            </div>
            
            <div className="luxury-glass-card p-4 max-w-sm mx-auto mb-6">
              <p className="luxury-text-small text-amber-700">
                כמו Uber - שני הצדדים צריכים לאשר. המוליך/ה יקבל/תקבל התראה ויוכל/תוכל לאשר או לסרב. 
                תקבל/י עדכון בהודעה כשיהיה התאמה!
              </p>
            </div>
            
            {weatherConsentAccepted && (
              <div className="luxury-glass-card p-3 max-w-sm mx-auto mb-6 border border-amber-200 bg-white">
                <p className="luxury-text-small text-amber-800 flex items-center justify-center gap-2">
                  <Shield className="h-4 w-4" />
                  הסכמה לתנאי מזג אוויר נרשמה
                </p>
              </div>
            )}
            
            <Button
              className="luxury-btn-primary luxury-shadow-xl px-12"
              onClick={() => setLocation("/dashboard")}
              data-testid="button-dashboard"
            >
              חזרה ללוח הבקרה
            </Button>
          </div>
        )}

        {/* Step 4: Confirmation (After Match) */}
        {step === "confirmation" && (
          <div className="text-center py-12 luxury-fade-in">
            <div className="w-24 h-24 rounded-full bg-gradient-to-r from-emerald-500 to-emerald-600 mx-auto flex items-center justify-center mb-6 luxury-shadow-xl">
              <Check className="h-12 w-12 text-white" />
            </div>
            {/* Personalized greeting */}
            {user?.displayName && (
              <p className="text-sm font-medium text-emerald-600 mb-1 tracking-wide">
                היי {user.displayName.split(' ')[0]}! 👋
              </p>
            )}
            <h2 className="luxury-heading-lg mb-4">יש התאמה! 🎉</h2>
            <p className="luxury-text-body max-w-md mx-auto mb-3">
              {walker?.businessName || walker?.displayName || 'המוליך/ה'} אישר/ה את ההזמנה!
            </p>
            {/* Booking reference card */}
            <div className="inline-flex flex-col items-center gap-1 px-5 py-3 rounded-2xl border border-slate-200 bg-white mb-4 mx-auto">
              <p className="text-xs text-slate-400 tracking-widest uppercase">מספר הזמנה</p>
              <p className="text-lg font-mono font-semibold text-slate-800 tracking-wider">
                #{bookingId || "—"}
              </p>
            </div>
            <p className="luxury-text-small max-w-md mx-auto mb-8">
              פרטי התשלום ומעקב GPS ישלחו בהודעה נפרדת.
            </p>

            {/* What happens next section */}
            <div className="bg-emerald-50/50 rounded-2xl p-6 border border-emerald-100 mb-4 text-right max-w-md mx-auto">
              <h3 className="text-emerald-900 font-semibold mb-3 flex items-center justify-end gap-2">
                <Clock className="h-4 w-4" />
                מה קורה עכשיו?
              </h3>
              <p className="text-emerald-800 text-sm leading-relaxed">
                המוליך שלך יאשר את ההזמנה תוך שעתיים. תקבל הודעת SMS והתראה באפליקציה ברגע שהכל מוכן.
              </p>
            </div>

            {/* Navigation to pickup address */}
            {(pickupDetails?.lat || (walker as any)?.latitude) && (
              <div className="max-w-md mx-auto mb-6 space-y-2">
                <p className="text-xs font-semibold text-gray-400 uppercase tracking-wider text-center mb-2">
                  ניווט לנקודת האיסוף
                </p>
                <div className="grid grid-cols-2 gap-2">
                  <a
                    href={`https://waze.com/ul?ll=${pickupDetails?.lat ?? (walker as any)?.latitude},${pickupDetails?.lng ?? (walker as any)?.longitude}&navigate=yes&zoom=17`}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="flex items-center justify-center gap-2 px-4 py-3 rounded-xl bg-cyan-50 border border-cyan-200 text-cyan-700 text-sm font-semibold hover:bg-cyan-100 transition-colors"
                  >
                    🚗 Waze
                  </a>
                  <a
                    href={`https://www.google.com/maps/dir/?api=1&destination=${pickupDetails?.lat ?? (walker as any)?.latitude},${pickupDetails?.lng ?? (walker as any)?.longitude}`}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="flex items-center justify-center gap-2 px-4 py-3 rounded-xl bg-blue-50 border border-blue-200 text-blue-700 text-sm font-semibold hover:bg-blue-100 transition-colors"
                  >
                    🗺️ Google Maps
                  </a>
                </div>
              </div>
            )}

            <div className="flex flex-col gap-3 max-w-md mx-auto mb-8">
              <Button
                className="luxury-btn-primary luxury-shadow-xl h-14"
                onClick={() => setLocation(`/booking-chat/${bookingId}`)}
                data-testid="button-message-walker"
              >
                <MessageSquare className="w-5 h-5 mr-2" />
                {isHebrew ? 'שלח הודעה למוליך' : 'Message your walker'}
              </Button>
              <Button
                variant="outline"
                className="luxury-btn-secondary h-12"
                onClick={() => setLocation("/dashboard")}
                data-testid="button-dashboard"
              >
                חזרה ללוח הבקרה
              </Button>
            </div>
          </div>
        )}
      </div>
      
      {/* Weather Consent Dialog */}
      <WeatherConsentDialog
        open={showWeatherConsent}
        onOpenChange={setShowWeatherConsent}
        onConsent={handleWeatherConsent}
        walkerName={walker?.businessName || walker?.displayName || 'המוליך/ה'}
        scheduledDate={selectedDate || new Date()}
      />
    </div>
  );
}
